SELECT e.event_id, m.case_id, e.activity, e.timestamp FROM (SELECT * FROM (SELECT 'EX:' || result_id event_id, student_id case_id, 'Degree Examination Taken' activity, examination_date timestamp FROM degree_examination_result UNION ALL SELECT 'REG:' || student_id || ':' || course_id event_id, student_id case_id, 'Course Registered' activity, registration_time timestamp FROM registration UNION ALL SELECT 'GRADE:' || g.assignment_id || ':' || g.instructor_id || ':' || g.grading_time event_id, a.student_id case_id, 'Assignment Graded' activity, g.grading_time timestamp FROM assignment_grading g JOIN assignment a ON a.assignment_id=g.assignment_id UNION ALL SELECT 'SIM:' || student_id || ':' || module_id || ':' || simulation_date event_id, student_id case_id, 'Simulation Experiment Completed' activity, simulation_date timestamp FROM student_simulation_experiment_result UNION ALL SELECT 'THESIS:' || thesis_id event_id, student_id case_id, 'Thesis Submitted' activity, submission_date timestamp FROM thesis) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT event_id,activity,occurred_at timestamp FROM assignment_activity) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT event_id,activity,occurred_at timestamp FROM simulation_module_activity) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT event_id,activity,occurred_at timestamp FROM student_simulation_experiment_result_activity) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT event_id,activity,occurred_at timestamp FROM thesis_activity) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT event_id,activity,occurred_at timestamp FROM course_activity) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT event_id,activity,occurred_at timestamp FROM task_activity) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:registration:' || student_id || ':' || course_id || ':1' event_id, 'Registration Requested' activity, registration_requested_at timestamp FROM registration WHERE registration_requested_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:registration:' || student_id || ':' || course_id || ':2' event_id, 'Registration Approved' activity, registration_approved_at timestamp FROM registration WHERE registration_approved_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:registration:' || student_id || ':' || course_id || ':3' event_id, 'Course Started' activity, course_started_at timestamp FROM registration WHERE course_started_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:registration:' || student_id || ':' || course_id || ':4' event_id, 'Course Assessment Completed' activity, course_assessment_completed_at timestamp FROM registration WHERE course_assessment_completed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:registration:' || student_id || ':' || course_id || ':5' event_id, 'Course Grade Finalized' activity, course_grade_finalized_at timestamp FROM registration WHERE course_grade_finalized_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:degree_examination_result:' || result_id || ':1' event_id, 'Examination Scheduled' activity, examination_scheduled_at timestamp FROM degree_examination_result WHERE examination_scheduled_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:degree_examination_result:' || result_id || ':2' event_id, 'Examination Checked In' activity, examination_checked_in_at timestamp FROM degree_examination_result WHERE examination_checked_in_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:degree_examination_result:' || result_id || ':3' event_id, 'Examination Score Published' activity, examination_score_published_at timestamp FROM degree_examination_result WHERE examination_score_published_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:degree_examination_result:' || result_id || ':4' event_id, 'Examination Result Reviewed' activity, examination_result_reviewed_at timestamp FROM degree_examination_result WHERE examination_result_reviewed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:assignment:' || assignment_id || ':1' event_id, 'Assignment Assigned' activity, assignment_assigned_at timestamp FROM assignment WHERE assignment_assigned_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:assignment:' || assignment_id || ':2' event_id, 'Assignment Submitted' activity, assignment_submitted_at timestamp FROM assignment WHERE assignment_submitted_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:assignment:' || assignment_id || ':' || CASE WHEN EXISTS (SELECT 1 FROM assignment_activity rv WHERE rv.assignment_id=assignment.assignment_id AND rv.activity='Assignment Revision Requested') THEN '6' ELSE '3' END event_id, 'Assignment Grade Finalized' activity, assignment_grade_finalized_at timestamp FROM assignment WHERE assignment_grade_finalized_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:thesis:' || thesis_id || ':1' event_id, 'Thesis Draft Registered' activity, thesis_draft_registered_at timestamp FROM thesis WHERE thesis_draft_registered_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:thesis:' || thesis_id || ':2' event_id, 'Thesis Review Started' activity, thesis_review_started_at timestamp FROM thesis WHERE thesis_review_started_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:thesis:' || thesis_id || ':' || CASE WHEN EXISTS (SELECT 1 FROM thesis_activity rv WHERE rv.thesis_id=thesis.thesis_id AND rv.activity='Thesis Revision Requested') THEN '5' ELSE '3' END event_id, 'Thesis Accepted' activity, thesis_accepted_at timestamp FROM thesis WHERE thesis_accepted_at IS NOT NULL)) e JOIN (SELECT 'EX:' || result_id event_id, result_id case_id FROM degree_examination_result UNION ALL SELECT event_id,case_id FROM lifecycle_case_link WHERE case_table='degree_examination_result') m ON m.event_id=e.event_id ORDER BY m.case_id,e.timestamp,e.event_id;
